import fs from 'node:fs/promises';
import crypto from 'node:crypto';
import { gunzipSync } from 'node:zlib';
import { installGithubStylesheetAliases } from './github_css.js';

const fixture = new URL('../tools/adblock/fixtures/github-stylesheets-20261108.json.gz', import.meta.url);
const escape = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replaceAll('/', '\\/');
const cssBody = source => source.replace(/\/\*# sourceMappingURL=[^*]*\*\/\s*$/, '').trimEnd();

export async function buildGithubStylesheetResources() {
    const reviewed = JSON.parse(gunzipSync(await fs.readFile(fixture)));
    for (const record of [reviewed.runtime, reviewed.primer, ...reviewed.pairs.flatMap(pair => [pair.chunk, pair.entry])]) {
        if (Buffer.byteLength(record.source) !== record.bytes ||
            crypto.createHash('sha256').update(record.source).digest('hex') !== record.sha256) {
            throw Error('Changed reviewed GitHub stylesheet source');
        }
    }
    const aliases = {};
    for (const { id, chunk, entry } of reviewed.pairs) {
        if (cssBody(chunk.source) !== cssBody(entry.source) ||
            new URL('.', chunk.url).href !== new URL('.', entry.url).href) {
            throw Error('GitHub stylesheet alias changes CSS or its URL base');
        }
        aliases[id] = { chunk: chunk.url.split('/').pop(), filename: entry.url.split('/').pop(), url: entry.url };
    }
    const originalURL = reviewed.runtime.url + '?vox_css_original=1';
    const code = `import {__webpack_require__ as runtime} from ${JSON.stringify(originalURL)};
export {runtime as __webpack_require__};
if(location.hostname==='github.com')(${installGithubStylesheetAliases.toString()})(runtime,document,${JSON.stringify(aliases)});
`;
    const resource = 'vox-github-css-loader.js';
    return { reviewed, aliases, originalURL,
        filters: `/^${escape(reviewed.runtime.url)}$/$script,match-case,domain=github.com,redirect=${resource}`,
        resources: new Map([[resource, code]]) };
}

export async function writeGithubStylesheetResources() {
    const { filters, resources } = await buildGithubStylesheetResources();
    await fs.writeFile(new URL('./github_css_resources.js', import.meta.url),
        '// Generated by github_css_builder.mjs from reviewed originals.\n' +
        'export const githubStylesheetFilters = ' + JSON.stringify('\n' + filters + '\n') + ';\n' +
        'export const githubStylesheetResources = new Map(' + JSON.stringify([...resources]) + ');\n');
}
